From bb6cd9638a46a5d830c2f74374a170ea89d1d7db Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 19:00:33 +0100
Subject: [PATCH] plasmaquick: offer Show Alternatives for widgets that failed
 to load

Widgets that fail to load, like Plasma 5 ones after upgrading, offered
no Show Alternatives, so replacing them lost their config. Offer it for
them too, and keep X-Plasma-Provides from legacy metadata.desktop files.

BUG: 497551
---
 .../packagestructure/plasma_applet_packagestructure.cpp   | 2 +-
 src/plasmaquick/plasmoid/containmentitem.cpp              | 8 ++++----
 2 files changed, 5 insertions(+), 5 deletions(-)

diff --git a/src/plasma/packagestructure/plasma_applet_packagestructure.cpp b/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
index d91a776ea..8f12957d8 100644
--- a/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
+++ b/src/plasma/packagestructure/plasma_applet_packagestructure.cpp
@@ -41,7 +41,7 @@ public:
             }
         }
         // The widge explorer uses it to display old incompatible plasmoids
-        KPackagePrivate::convertCompatMetaDataDesktopFile(package);
+        KPackagePrivate::convertCompatMetaDataDesktopFile(package, {{QStringLiteral("X-Plasma-Provides"), QMetaType::QStringList}});
     }
 };

diff --git a/src/plasmaquick/plasmoid/containmentitem.cpp b/src/plasmaquick/plasmoid/containmentitem.cpp
index d8f65fc21..5977f355d 100644
--- a/src/plasmaquick/plasmoid/containmentitem.cpp
+++ b/src/plasmaquick/plasmoid/containmentitem.cpp
@@ -967,10 +967,10 @@ void ContainmentItem::addAppletActions(QMenu *desktopMenu, Plasma::Applet *apple
         if (configureApplet && configureApplet->isEnabled()) {
             desktopMenu->addAction(configureApplet);
         }
-        QAction *appletAlternatives = applet->internalAction(QStringLiteral("alternatives"));
-        if (appletAlternatives && appletAlternatives->isEnabled()) {
-            desktopMenu->addAction(appletAlternatives);
-        }
+    }
+    QAction *appletAlternatives = applet->internalAction(QStringLiteral("alternatives"));
+    if (appletAlternatives && appletAlternatives->isEnabled()) {
+        desktopMenu->addAction(appletAlternatives);
     }

     desktopMenu->addSeparator();
-- 
2.53.0
